import type { GameBank } from '@/lib/games/explanations/types'

/**
 * Quote Detective: which set text a line is from, who says it and when, which
 * line supports a point, and which word in a line does the work.
 *
 * Moved out of src/app/games/quote-detective/page.tsx on 16 October 2026, when
 * every answer gained an explanation (src/lib/games/explanations/types.ts).
 *
 * HOW THE QUOTATIONS WERE CHECKED (found writing those explanations, which
 * name each speaker and scene). Words AND speaker, act, chapter or stave, since
 * a guard that checks only words has missed misattributions on this site
 * before. The 73 from public-domain texts were found word for word in the held
 * editions (src/data/full-texts: Macbeth, Romeo and Juliet, A Christmas Carol,
 * Jekyll and Hyde, Animal Farm) with their speaker and section. The 37 from
 * texts in copyright (An Inspector Calls, Lord of the Flies, Of Mice and Men,
 * To Kill a Mockingbird) were checked against the text's study guide where it
 * quotes the line, two scans of the published Of Mice and Men on the Internet
 * Archive, and published quotation sources for the rest.
 *
 * WHAT WAS WRONG. Ten quotations were not the text's words:
 *
 *   - "He was as solitary as an oyster." is in no edition of A Christmas
 *     Carol. Stave One describes Scrooge as "Secret, and self-contained, and
 *     solitary as an oyster.", which is now the quotation.
 *   - "We are all responsible for each other." is the usual paraphrase of the
 *     Inspector. He says "We are responsible for each other." (Act 3), which is
 *     now the quotation.
 *   - "The girl had been happy - hadn't she?" is in no printing of An
 *     Inspector Calls and was found in no source. It is replaced by Gerald's
 *     "I didn't feel about her as she felt about me." (Act 2), which
 *     src/data/study-guides/an-inspector-calls.ts checked against the
 *     published text.
 *   - "Tell me about the rabbits, George." is a famous misquotation that
 *     Steinbeck never wrote (src/data/study-guides/of-mice-and-men.ts says the
 *     same). It is replaced by Lennie's "I remember about the rabbits,
 *     George." (Chapter 1), found in both scans.
 *   - "Mockingbirds don't do one thing but sing their hearts out for us."
 *     joined the start of one of Miss Maudie's sentences to the end of
 *     another. It is now her first sentence, as the To Kill a Mockingbird
 *     guide quotes it.
 *   - "what real courage is, ... courage is a man with a gun." cut the words
 *     in which Atticus rejects that idea, so it said the opposite of what he
 *     means. It is now "I wanted you to see what real courage is." (Chapter
 *     11).
 *   - "You never really understand a person until you climb into his skin."
 *     had lost the middle of Atticus's sentence (Chapter 3) with no ellipsis;
 *     the ellipsis now marks the cut.
 *   - "Bah! Humbug!", "The rules! You're breaking the rules!" and "Ain't many
 *     guys travel around together. I don't know why." each ran across a speech
 *     tag (Scrooge's, Ralph's, Slim's) with no ellipsis; one now marks it, as
 *     in the site's other corrected quotations.
 *
 * THREE QUOTATIONS SHORTENED (16 October 2026, by the second reader). The site
 * quotes a text in copyright to at most FAIR_DEALING.quoteWords words
 * (src/lib/study-guides/fair-dealing.ts), and three ran to fifteen. Each was
 * cut by deletion only, and an ellipsis marks the cut: Lennie's line about
 * looking after each other (Of Mice and Men, Chapter 1) loses "and"; Eric's
 * line to his father (An Inspector Calls, Act 3) stops at "go to", as
 * src/data/study-guides/an-inspector-calls.ts quotes it; Curley's wife's threat
 * to Crooks (Chapter 4) loses "on a tree".
 * src/__tests__/no-game-quotes-over-the-fair-dealing-limit.test.ts holds them.
 *
 * Every other quotation, and every answer, is unchanged.
 *
 * REBUILT FOR DEPTH (24 October 2026). The founder, that day: the games are
 * "too obvious and easy. not enough depth and content". Measured that day
 * (.tmp-games-audit, read only): the game asked one thing, which text a line
 * is from, of 110 quotations from nine texts; a student who knew only the
 * titles could guess 46 per cent of it; three lines were asked twice; 8 of the
 * 14 Jekyll and Hyde lines were from Chapter 10 and 11 of the 15 A Christmas
 * Carol lines from Stave One; and a Cambridge 0475 student, none of whose
 * texts was here, was dealt the GCSE bank with the board badge hidden. It now
 * asks four things, of 764 questions on 100 set texts: every text a board
 * sets that has a study guide with key quotations, Cambridge's included, apart
 * from Dylan Thomas's "Do not go gentle into that good night", left out because
 * the writers' tools are stopped by a content filter on it.
 *
 *   tier 1, `text`     which text is it from: the question the game always
 *                      asked, its four titles still drawn by the page from
 *                      the student's board;
 *   tier 2, `speaker`  who says it, and when, against the same speaker at
 *                      another moment or another character at that moment
 *                      (for a poem or a piece of non-fiction, when in it);
 *   tier 3, `point`    which of four lines from one text supports a claim;
 *   tier 3, `word`     which word in a line does a named job, or what one
 *                      word suggests.
 *
 * WHERE THE NEW LINES COME FROM. A text in UK copyright is quoted only where
 * its study guide quotes it (keyQuotes in src/data/study-guides, or the
 * key-quotes data or revision notes the guide points to), within FAIR_DEALING,
 * and a point question on one shows at most 50 words; there is none on a poem
 * in copyright, because four lines of a short poem on one screen is too much
 * of it. A text out of UK copyright is quoted word for word from its held
 * edition in src/data/full-texts, with the speaker and place that edition
 * gives. `where` places every line (`optionWhere`, every option of a point
 * question), and `facts` gives the line and its scene (for a poem or other
 * short work, the whole work), so the dealer never puts one line asked two
 * ways, or two lines from one scene, in one round.
 *
 * WHAT CHANGED IN THE QUESTIONS IT ALREADY HAD.
 *
 *   - Five removed as repeats: "Good night, good night! Parting is such sweet
 *     sorrow" ("Parting is such sweet sorrow." stays); "All animals are
 *     equal." (the Chapter 10 commandment stays); "that man is not truly one,
 *     but truly two." ("Man is not truly one, but truly two." stays); and
 *     the Inspector's "We are responsible for each other." and "We don't live
 *     alone. We are members of one body.", both inside "We are members of one
 *     body. We are responsible for each other.", which stays.
 *   - Four cut by deletion, an ellipsis marking each cut, because a name in
 *     them gave the title away: "Mr Birling" from "Public men, Mr Birling,
 *     have responsibilities ..."; "Scrooge" from "... at the grind-stone,
 *     Scrooge!"; "Ralph" from "Ralph wept for the end of innocence ...";
 *     "George" from "I remember about the rabbits, George." Each keeps the
 *     key it always had, in `id`, so a student's record of it still matches.
 *   - Every question the bank had is tier 1, and every one now records where
 *     its line is.
 *
 * CHECKED BY A SECOND READER (24 October 2026), as the founder decided
 * (src/lib/games/explanations/types.ts). Every question was read against its
 * source: speaker and place against the speech headings and sections of the
 * held editions, and for a text in copyright against its guide's key
 * quotations, timeline and characters; every quotation again word for word,
 * punctuation and case kept. What was wrong, and what changed:
 *
 *   - Eight legacy "which text" lines named their title or a character who
 *     gives it away, against the rule the new lines keep: "O Romeo, Romeo!
 *     Wherefore art thou Romeo?", "For never was a story of more woe than this
 *     of Juliet and her Romeo.", "I will honour Christmas in my heart, ...",
 *     "Old Marley was as dead as a door-nail.", "Darkness is cheap, and
 *     Scrooge liked it.", "If he be Mr Hyde... I shall be Mr Seek.", "The
 *     moment I choose, I can be rid of Mr Hyde." and "Napoleon is always
 *     right." Removed.
 *   - Animal Farm, "Snowball has done this thing!": the wrong option
 *     "Napoleon, sniffing out Snowball's traces" was the same moment (in
 *     Chapter 6 he snuffs at the ground among the ruins just before the line,
 *     and at the footprints just after). Replaced with the dogs chasing
 *     Snowball off the farm.
 *   - Beyond the Sky and the Earth: a "which text" line held "earth", a word
 *     of its own title. Replaced with another of its guide's key quotations.
 *   - Three answers shared a word with the line that no other option shared,
 *     and were reworded without it: Piano ("back"), Boys Don't Cry
 *     ("Melanie"), The Necklace ("years"). In Hide and Seek the answer was
 *     half as long again as any other option, so it was shortened and two
 *     wrong options lengthened.
 *   - Two quotations differed from the held edition: Romeo and Juliet, "too
 *     sudden;" where the edition prints a comma; The Tyger, the comma after
 *     "spears" restored.
 *   - Two quotations printed an en dash; they now print the spaced hyphen
 *     the bank uses for a dash everywhere else (Journey's End, Young and
 *     dyslexic).
 *   - Three explanations corrected: Juliet's stars speech (the held edition
 *     reads "when I shall die", her death, not Romeo's), and two An Inspector
 *     Calls explanations that quoted or paraphrased another question's answer.
 *   - The anthology non-fiction was placed two ways for the same texts, by
 *     paragraph (which nothing held can check) and by the anthology's line
 *     numbers. Every place is now the line its guide gives.
 */

export type QuoteKind = 'text' | 'speaker' | 'point' | 'word'

export interface QuoteEntry {
  /** What is asked (see above). */
  kind: QuoteKind
  /** 1 recall, 2 understanding, 3 the exam skill (src/lib/games/deal-round.ts deals the easier first). */
  tier: 1 | 2 | 3
  /** The text, as the game names it: a key of TEXT_SLUGS. */
  text: string
  /** Where the line is: "Act 2, Scene 2", "Stave 3", "Chapter 5", "Stanza 2", or for the anthology, "Line 34". */
  where: string
  /** The key a "which text" question has always had, where its line was cut later. */
  id?: string
  /** The line shown, exactly as the source prints it. Empty for a point question. */
  quote: string
  /** The question asked, for every kind but `text`. */
  prompt?: string
  /** Four options, for every kind but `text` (whose titles the page draws). */
  options?: readonly string[]
  /** The right option, for every kind but `text`. */
  answer?: string
  /** For a point question: where each option's line is, in the same order. */
  optionWhere?: readonly string[]
  /**
   * Another line this question gives away, where the two are worded differently
   * ("Four legs good, two legs BETTER" shows the earlier maxim): it is one of
   * the question's facts, so the two are never dealt in one round.
   */
  line?: string
}

