/** A line as a fact: its words alone, so a line cut two ways is still one line. */
const lineFact = (line: string) =>
  `line: ${line
    .toLowerCase()
    .replace(/[‘’]/g, "'")
    .replace(/[^a-z0-9']+/g, ' ')
    .trim()}`

export const BANK: GameBank<QuoteEntry> = {
  slug: 'quote-detective',
  items: QUOTE_BANK,
  // A "which text" question is named by its line, as it always was (by its old
  // line where that was cut later); the other kinds by the kind and what they ask.
  key: (q) =>
    q.kind === 'text'
      ? (q.id ?? q.quote)
      : q.kind === 'speaker'
        ? `speaker: ${q.quote}`
        : q.kind === 'point'
          ? `point: ${q.text}: ${q.prompt}`
          : `word: ${q.quote} | ${q.prompt}`,
  answer: (q) => (q.kind === 'text' ? q.text : (q.answer ?? '')),
  // The page deals a "which text" question's right title and three others drawn
  // at random from the student's board, so it has no fixed set of options.
  options: (q) => (q.kind === 'text' ? null : (q.options ?? [])),
  tag: (q) => q.text,
  tier: (q) => q.tier,
  // Every line the question shows, and the scene of its answer.
  facts: (q) => [
    ...(q.kind === 'point' ? (q.options ?? []) : [q.quote]).map(lineFact),
    ...(q.line ? [lineFact(q.line)] : []),
    WHOLE_WORKS.has(q.text) ? `scene: ${q.text}` : `scene: ${q.text}, ${q.where}`,
  ],
  deepened: '2026-10-24',
  // A "which word does the work" answer is a word of its own line ("that",
  // "still", "must"): found in another question's explanation it tells no
  // one which word of this line does the work (src/lib/games/give-aways.ts).
  ordinaryAnswer: (q) => q.kind === 'word',
}
